class MaskMarket:
    def __init__(self, types_available: List[str], price_by_type: Dict[str, float], initial_supply_by_type: Dict[str, int], restock_rate_by_type: Dict[str, int], rationing_rules: Dict[str, int]):
        self.types_available = types_available
        self.price_by_type = price_by_type
        self.inventory_by_type = {t: max(0, int(initial_supply_by_type.get(t, 0))) for t in types_available}
        self.restock_rate_by_type = restock_rate_by_type
        self.rationing_rules = rationing_rules
    def restock(self):
        for t in self.types_available:
            self.inventory_by_type[t] += int(self.restock_rate_by_type.get(t, 0))
    def sell_masks(self, mask_type: str, desired_qty: int) -> int:
        inv = self.inventory_by_type.get(mask_type, 0)
        limit = self.rationing_rules.get(mask_type, desired_qty)
        qty = max(0, min(desired_qty, limit, inv))
        self.inventory_by_type[mask_type] = inv - qty
        return qty

